<script setup lang="ts">
import {computed,ref} from 'vue';
import PufferMark from './PufferMark.vue';
import type {Theme,Vod,Category} from '@/domain/types';
const props=withDefaults(defineProps<{theme:Theme;items:Vod[];categories?:Category[];sectionItems?:Record<string,Vod[]>;demo?:boolean;loading?:boolean;error?:string;preview?:boolean;selected?:string;compact?:boolean;device?:'mobile'|'tablet'|'tv'|'web';activeTab?:string;selectedCategory?:string}>(),{categories:()=>[],sectionItems:()=>({}),demo:false,loading:false,error:'',preview:false,selected:'',compact:false,device:'mobile',activeTab:'home',selectedCategory:''});
const emit=defineEmits<{(event:'open',vod:Vod):void;(event:'search',keyword:string):void;(event:'category',id:string):void;(event:'select',id:string):void;(event:'retry'):void;(event:'tab',tab:string):void}>();
const keyword=ref('');
const cinemaRoot=ref<{ $el?:HTMLElement }|HTMLElement|null>(null);
const skeleton=computed(()=>props.theme.skeleton?.kind || (props.theme.layout.heroStyle==='minimal'?'classic':'cinema'));
const hero=computed(()=>props.items[0]);
const css=computed(()=>({'--bg':props.theme.colors.background,'--surface':props.theme.colors.surface,'--ink':props.theme.colors.text,'--muted':props.theme.colors.muted,'--accent':props.theme.colors.accent,'--radius':props.theme.layout.posterRadius+'px'}));
const festival=computed(()=>({spring:'✦ 新春好戏，福气登场',christmas:'✧ 冬日光影，温暖相伴',midautumn:'☾ 月圆时，一起看部电影'}[props.theme.festival.kind] || ''));
function sectionVods(section:any){return (props.sectionItems[section.id] || (section.source==='category'?props.items.filter(v=>v.categoryId===section.categoryId):props.items)).slice(0,section.limit);}
function chooseCategory(id:string){emit('category',id);}
function handleTvKey(event:KeyboardEvent){
  // #ifdef H5
  if(props.device!=='tv'||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Enter'].includes(event.key))return;
  const instance=cinemaRoot.value;
  const root=instance instanceof HTMLElement?instance:instance?.$el;
  if(!(root instanceof HTMLElement))return;
  const targets=Array.from(root.querySelectorAll<HTMLElement>('.tv-target')).filter(el=>el.getBoundingClientRect().width>0);
  if(!targets.length)return;
  event.preventDefault();event.stopPropagation();
  const current=document.activeElement as HTMLElement;
  if(!targets.includes(current)){targets[0].focus();return;}
  if(event.key==='Enter'){current.click();return;}
  const from=current.getBoundingClientRect(),x=from.left+from.width/2,y=from.top+from.height/2;
  const horizontal=event.key==='ArrowLeft'||event.key==='ArrowRight',sign=event.key==='ArrowLeft'||event.key==='ArrowUp'?-1:1;
  let best:HTMLElement|undefined,score=Infinity;
  for(const el of targets){if(el===current)continue;const rect=el.getBoundingClientRect(),dx=rect.left+rect.width/2-x,dy=rect.top+rect.height/2-y;const forward=(horizontal?dx:dy)*sign;if(forward<4)continue;const sideways=Math.abs(horizontal?dy:dx);const distance=forward+sideways*3;if(distance<score){best=el;score=distance;}}
  if(best){best.focus();best.scrollIntoView({block:'nearest',inline:'nearest'});}
  // #endif
}
</script>
<template>
<view ref="cinemaRoot" class="cinema" :class="[{compact:compact,dense:theme.layout.density==='compact'},'skeleton-'+skeleton,'device-'+device]" :style="css" :tabindex="device==='tv'?0:undefined" @keydown="handleTvKey">
  <view class="cinema-top"><view class="brand"><PufferMark :color="theme.colors.accent"/><text>{{theme.brand.name}}</text><text class="brand-label">CINEMA CLUB</text></view><view class="top-tools"><text class="demo-badge" v-if="demo">设计示例</text><text class="top-user" @click="emit('tab','mine')">◉</text></view></view>
  <view class="search-row"><view class="search-box"><text>⌕</text><input v-model="keyword" placeholder="搜索片名，发现好故事" confirm-type="search" @confirm="emit('search',keyword)"/><text class="search-go" @click="emit('search',keyword)">搜索</text></view></view>
  <view class="categories"><text class="tv-target" :tabindex="device==='tv'?0:undefined" role="button" :class="{active:!selectedCategory}" @click="chooseCategory('')">精选</text><text v-for="category in categories" :key="category.id" class="tv-target" :tabindex="device==='tv'?0:undefined" role="button" :class="{active:selectedCategory===category.id}" @click="chooseCategory(category.id)">{{category.name}}</text></view>
  <view v-if="theme.festival.enabled && festival" class="festival">{{festival}} <text>✦</text></view>
  <view v-if="hero" class="hero" :class="{selected:selected==='hero'}" @click="preview ? emit('select','hero') : undefined">
    <image class="hero-art" :src="hero.poster" mode="aspectFill"/>
    <view class="hero-shade"/><view class="hero-copy"><view class="eyebrow"><text class="live-dot"/> HETUN SELECTED · {{theme.brand.name}}精选</view><text class="hero-title">{{hero.title}}</text><view class="hero-meta"><text class="score">{{hero.score || '精选'}}</text><text>{{hero.year}} · {{hero.category}}</text><text>{{hero.note}}</text></view><text class="hero-line">{{demo?'在故事的彼岸，找到属于自己的片刻。':theme.brand.tagline}}</text><view class="hero-actions"><button class="watch tv-target" :tabindex="device==='tv'?0:undefined" @click.stop="emit('open',hero)"><text>▶</text> {{demo?'查看示例':'立即观看'}}</button><text class="hero-detail" @click.stop="emit('open',hero)">了解影片 ↗</text></view></view>
    <view class="hero-counter">01 <text>/ {{items.length.toString().padStart(2,'0')}}</text></view>
  </view>
  <view v-if="loading" class="notice">正在读取片库…</view><view v-if="error" class="notice error"><text>{{error}}</text><button @click="emit('retry')">重试连接</button></view>
  <view v-if="theme.announcement.enabled" class="announcement"><text class="announcement-label">放映室来信</text><text>{{theme.announcement.text}}</text><text class="arrow">↗</text></view>
  <view class="sections"><view v-for="section in theme.sections.filter(s=>s.enabled)" :key="section.id" class="film-section" :class="{selected:selected===section.id}" @click="preview ? emit('select',section.id) : undefined">
    <view class="section-head"><view><text class="section-title">{{section.title}}</text><text class="section-subtitle">{{section.subtitle}}</text></view><text class="see-all" @click.stop="preview ? emit('select',section.id) : emit('category',section.categoryId)">{{preview?'编辑模块':'更多'}} ↗</text></view>
    <view :class="['film-grid',section.kind]" :style="{'--columns':section.columns}">
      <view class="film-card tv-target" :tabindex="device==='tv'?0:undefined" role="button" :aria-label="'查看影片：'+film.title" v-for="(film,index) in sectionVods(section)" :key="film.id" @click.stop="preview ? emit('select',section.id) : emit('open',film)"><view class="poster-wrap"><image v-if="film.poster" class="poster-image" :src="film.poster" mode="aspectFill"/><view v-else class="poster-placeholder">{{film.title}}</view><text v-if="film.score" class="poster-score">{{film.score}}</text><text v-if="section.kind==='ranking'" class="rank">{{index+1}}</text><text class="poster-note">{{film.note}}</text></view><text class="film-title">{{film.title}}</text><text class="film-meta">{{film.year}} · {{film.category}}</text></view>
    </view><view v-if="!sectionVods(section).length" class="empty-section">{{demo?'这个分类还没有示例影片':'此模块暂无影片，请调整内容来源。'}}</view>
  </view></view>
  <view class="cinema-footer"><PufferMark :color="theme.colors.accent"/><text>{{theme.brand.tagline}}</text><text class="footer-small">HETUN · YOUR LITTLE CINEMA</text></view>
  <view class="bottom-nav"><view class="nav-item" :class="{active:activeTab==='home'}" @click="emit('tab','home')"><text>⌂</text><text>发现</text></view><view class="nav-item" :class="{active:activeTab==='library'}" @click="emit('tab','library')"><text>▤</text><text>片单</text></view><view class="nav-item" :class="{active:activeTab==='history'}" @click="emit('tab','history')"><text>◷</text><text>足迹</text></view><view class="nav-item" :class="{active:activeTab==='mine'}" @click="emit('tab','mine')"><text>♙</text><text>我的</text></view></view>
</view>
</template>
